#!/usr/bin/env bash

# Compiles the Wren modules the Wren converter generated by importing every one of them with wren_cli. Wren imports are
# relative paths so the hand written runtime, the Wren sources of the dependencies (META-INF/wren/src of their jars),
# and this project are copied to one tree first. This project's sources are written to <output>/src.
# Arguments: source_dir output_dir object_dir dependency_dir runtime_dir compiler "flags" artifactId fail_on_error

set -uo pipefail

export PATH="/usr/local/bin:/usr/bin:/bin:$PATH"

source_dir="$(cygpath -u "$1")"
output_dir="$(cygpath -u "$2")"
object_dir="$(cygpath -u "$3")"
dependency_dir="$(cygpath -u "$4")"
runtime_dir="$(cygpath -u "$5")"
compiler="$(cygpath -u "$6")"
read -r -a compiler_flags <<< "$7"
artifact="$8"
fail_on_error="${9:-true}"

if [ ! -d "$source_dir" ]; then
    echo "No Wren sources: $source_dir"
    exit 0
fi

rm -rf "$output_dir" "$object_dir"
tree="$object_dir/tree"
mkdir -p "$output_dir/src" "$tree"
cp -R "$source_dir/." "$output_dir/src/"
cp "$runtime_dir"/*.wren "$tree/"
if [ -d "$dependency_dir/src" ]; then
    cp -R "$dependency_dir/src/." "$tree/"
fi
cp -R "$source_dir/." "$tree/"

cd "$tree" || exit 1
check="jcheck_$artifact.wren"
count=0
while IFS= read -r file; do
    module="${file#"$source_dir"/}"
    echo "import \"./${module%.wren}\"" >> "$check"
    count=$((count + 1))
done < <(find "$source_dir" -type f -name '*.wren' | sort)
echo "System.print(\"Wren compiled: $artifact\")" >> "$check"
echo "Wren modules: $count"

output="$("$compiler" "${compiler_flags[@]}" "$check" 2>&1)"
status=$?
echo "$output"
if [ "$status" = "0" ] && ! echo "$output" | grep -q -E 'Error|Could not'; then
    exit 0
fi
echo "Wren build failed: $artifact" >&2
if [ "$fail_on_error" = "true" ]; then
    exit 1
fi
exit 0
